href
<js>
burl=String(source.bookSourceUrl).replace(/#.*/,'').replace(/m\./,'www.');
url=burl+"ajaxChapter.php?time="+(new Date()).valueOf();
aid=result.match(/\d+\/(\d+)\//)[1];
cid=result.match(/\d+\/\d+\/(\d+)/)[1];
ref=burl+result;
post={
  'method':'POST',
  'body':'aid='+aid+'&cid='+cid,
  'headers':{"Referer":ref}
}
url+','+JSON.stringify(post)
</js>

